-- Eight additional questions for each existing concept; preserve prior content and progress.
INSERT INTO questions (prompt, options, correct_option_id, explanation, concept_id)
SELECT seed.prompt, seed.options::jsonb, seed.answer, seed.explanation, c.id
FROM (VALUES
    ('A running process uses its entire time quantum without finishing. If it remains runnable, which state does preemption normally move it to?',
     '{"A":"Ready","B":"Blocked on disk I/O","C":"Terminated","D":"New"}', 'A',
     'Preemption removes the process from the CPU but does not make it unable to run. It returns to the ready state to await another turn.', 'Processes'),
    ('Which action normally requires a system call rather than only ordinary user-mode instructions?',
     '{"A":"Adding two local integers","B":"Requesting that the OS open a file","C":"Comparing two local array elements","D":"Calling a function that only computes a sum"}', 'B',
     'Opening a file requests an operating-system service. Arithmetic and ordinary local computations can execute entirely in user mode.', 'Processes'),
    ('Why does a CPU distinguish user mode from kernel mode?',
     '{"A":"To give every user process unrestricted device access","B":"To prevent programs from calling functions","C":"To restrict privileged operations and protect the system","D":"To guarantee that all programs finish simultaneously"}', 'C',
     'The privilege distinction limits operations such as direct device control and memory-management changes to trusted kernel execution.', 'Processes'),
    ('On UNIX, a child has terminated but its parent has not yet collected its exit status. What is this child commonly called?',
     '{"A":"A ready process","B":"A running daemon","C":"A blocked producer","D":"A zombie process"}', 'D',
     'A zombie retains termination information until its parent or another responsible process collects it. It is not still executing its program.', 'Processes'),
    ('Which UNIX operation can a parent use to collect a terminated child process exit status?',
     '{"A":"wait or waitpid","B":"An ordinary integer addition","C":"Changing the parent executable filename","D":"Reading its own program counter"}', 'A',
     'The wait family lets a parent observe child state changes and reap terminated children, collecting their exit status.', 'Processes'),
    ('What is the purpose of a process identifier (PID)?',
     '{"A":"To specify the number of CPU registers","B":"To identify a process within the operating system","C":"To encode the complete program source","D":"To guarantee a permanent identity across all future restarts"}', 'B',
     'A PID identifies a process for operations such as management and signaling. Identifiers can be reused after processes exit.', 'Processes'),
    ('A timer interrupt lets the OS regain control while a user process is computing. What capability does this support?',
     '{"A":"Eliminating every interrupt handler","B":"Making all user instructions privileged","C":"Preemptive scheduling","D":"Preventing any context switch"}', 'C',
     'Timer interrupts provide opportunities for the kernel to preempt execution and allocate CPU time even when a program does not voluntarily yield.', 'Processes'),
    ('How can two processes executing the same program differ?',
     '{"A":"They must always share every register value","B":"They must have identical execution histories","C":"They cannot exist at the same time","D":"They can have different execution states and private data"}', 'D',
     'A program is code, while each process is an execution instance with its own state and resources. Instances can progress differently.', 'Processes'),
    ('A program has four independent CPU-bound worker threads but only one CPU core. Which expectation is justified?',
     '{"A":"The workers can be interleaved, but cannot all execute instructions simultaneously on that core","B":"All four workers always finish four times faster","C":"Each thread creates an extra physical core","D":"The OS cannot schedule any of them"}', 'A',
     'One core can interleave threads for concurrency. CPU-bound speedup from simultaneous execution requires additional execution capacity.', 'Threads'),
    ('What does thread-local storage provide?',
     '{"A":"One unavoidable shared copy for all threads","B":"A distinct value associated with each thread for a thread-local variable","C":"A different executable file for every function call","D":"A substitute for all communication between threads"}', 'B',
     'Thread-local storage associates a separate instance of a variable with each thread. Other process data can still be shared.', 'Threads'),
    ('In a one-to-one threading model, what is the relationship between user threads and kernel threads?',
     '{"A":"All user threads map to one kernel thread","B":"Kernel threads are forbidden","C":"Each user thread maps to a corresponding kernel thread","D":"Each CPU core has exactly one process forever"}', 'C',
     'One-to-one mapping exposes each thread as a schedulable kernel thread, allowing the kernel to schedule them independently.', 'Threads'),
    ('In a many-to-one model, a user thread makes a blocking system call that blocks its sole underlying kernel thread. What can happen to its peer user threads?',
     '{"A":"They automatically migrate to different computers","B":"They all become kernel interrupt handlers","C":"They necessarily continue on separate cores","D":"They cannot execute through that blocked kernel thread until it becomes runnable"}', 'D',
     'When all user threads depend on one kernel thread, blocking that kernel thread can prevent the others from executing as well.', 'Threads'),
    ('Why might a server use a bounded worker-thread pool instead of creating an unbounded number of threads?',
     '{"A":"To limit resource use and reuse workers across tasks","B":"To ensure tasks never wait","C":"To make every task CPU-independent","D":"To remove the need to handle failed tasks"}', 'A',
     'A bounded pool caps active workers and can avoid repeated thread creation. Queuing and overload handling are still necessary.', 'Threads'),
    ('A parent thread creates a worker and immediately joins it before creating the next worker. What is the likely effect on overlap between workers?',
     '{"A":"All workers necessarily execute in parallel","B":"Workers execute sequentially because each is awaited before the next is created","C":"Every join creates a new CPU core","D":"Joining automatically duplicates all workers"}', 'B',
     'Joining immediately waits for the current worker to finish before the next is created, preventing overlap between these workers.', 'Threads'),
    ('A worker exits while another thread still holds a pointer to an object on that worker stack. What is the concern?',
     '{"A":"The object is automatically copied into every thread","B":"The pointer becomes a process ID","C":"The pointer can refer to storage whose lifetime has ended","D":"Every stack object becomes permanent"}', 'C',
     'Sharing an address does not extend the lifetime of the object. Accessing a worker stack object after its lifetime ends is unsafe.', 'Threads'),
    ('A computation is 50 percent inherently serial and 50 percent perfectly parallelizable. Ignoring overhead, what is its maximum speedup with arbitrarily many processors?',
     '{"A":"Unlimited","B":"50 times","C":"4 times","D":"2 times"}', 'D',
     'The serial half still takes half the original execution time even if the parallel half becomes negligible, limiting speedup to 1 / 0.5 = 2.', 'Threads'),
    ('Three jobs arrive together and run nonpreemptively in FCFS order with CPU bursts 4, 3, and 2. Ignoring overhead, how long does the third wait before starting?',
     '{"A":"7 time units","B":"2 time units","C":"4 time units","D":"9 time units"}', 'A',
     'The third job waits for the first two bursts: 4 + 3 = 7 time units.', 'CPU Scheduling'),
    ('Jobs A, B, and C are ready at time zero with known CPU bursts 6, 2, and 4. Which order does nonpreemptive shortest-job-first choose?',
     '{"A":"A, B, C","B":"B, C, A","C":"C, A, B","D":"A, C, B"}', 'B',
     'With all jobs available, shortest-job-first chooses ascending burst lengths: B with 2, C with 4, then A with 6.', 'CPU Scheduling'),
    ('Round-robin uses a quantum of 2. A and B arrive at time zero in that order with bursts 3 and 2. Ignoring overhead, when does B finish?',
     '{"A":"Time 2","B":"Time 3","C":"Time 4","D":"Time 5"}', 'C',
     'A runs from 0 to 2, then B runs from 2 to 4 and finishes. A has one unit remaining.', 'CPU Scheduling'),
    ('If a round-robin quantum exceeds every ready job CPU burst and no new jobs arrive, what behavior does it resemble?',
     '{"A":"Shortest-remaining-time-first","B":"Random selection after every instruction","C":"Continuous preemption of every job","D":"FCFS execution in ready-queue order"}', 'D',
     'Each job completes its burst before its quantum expires, so execution follows the ready-queue order without quantum-driven preemption.', 'CPU Scheduling'),
    ('A system completes 20 jobs in 5 seconds. What is its throughput over that interval?',
     '{"A":"4 jobs per second","B":"25 jobs per second","C":"100 jobs per second","D":"0.25 jobs per second"}', 'A',
     'Throughput is completed work divided by elapsed time: 20 / 5 = 4 jobs per second.', 'CPU Scheduling'),
    ('Which scheduling measure most directly captures how soon an interactive task first receives CPU service after arrival?',
     '{"A":"Total completed job count","B":"Response time","C":"Total physical memory","D":"Executable file size"}', 'B',
     'Response time measures the delay from arrival to first service. Turnaround instead measures the delay to completion.', 'CPU Scheduling'),
    ('A low-priority thread holds a mutex needed by a high-priority thread, while a medium-priority thread keeps preempting the lock holder. What is this called?',
     '{"A":"Page replacement","B":"External fragmentation","C":"Priority inversion","D":"A successful barrier completion"}', 'C',
     'The high-priority thread is indirectly delayed by medium-priority work because it depends on a low-priority lock holder.', 'CPU Scheduling'),
    ('How can priority inheritance help when a high-priority thread is blocked on a mutex held by a lower-priority thread?',
     '{"A":"By permanently discarding the blocked thread","B":"By automatically duplicating the mutex","C":"By forbidding the lock holder from running","D":"By temporarily raising the lock holder priority so it can finish and release the mutex"}', 'D',
     'Priority inheritance lets the lock holder run with inherited priority while needed, reducing delays caused by intervening medium-priority work.', 'CPU Scheduling'),
    ('A UNIX pipe has no buffered data and every write descriptor has been closed. What does a read normally return?',
     '{"A":"End of file, indicated by zero bytes read","B":"An infinite stream of zero-valued bytes","C":"A new process identifier","D":"The source code of the writer"}', 'A',
     'Once the buffer is drained and no write end remains open, a read reports EOF. An empty pipe with a writer still open has different blocking behavior.', 'Interprocess Communication'),
    ('A reader waits for EOF on a pipe, but another process accidentally keeps an unused write descriptor open. What can happen after the buffer is drained?',
     '{"A":"EOF is guaranteed immediately","B":"A blocking read can keep waiting because a writer is still open","C":"The reader automatically closes all remote descriptors","D":"The pipe necessarily becomes a regular disk file"}', 'B',
     'EOF depends on all write descriptors being closed. A leaked write descriptor can make a blocking reader wait for more data.', 'Interprocess Communication'),
    ('An application sends two logical records over a TCP connection. What must the receiver account for?',
     '{"A":"Each send always becomes exactly one matching receive","B":"TCP automatically labels application records","C":"TCP provides a byte stream, so the application needs record framing","D":"TCP forbids receiving a partial record"}', 'C',
     'TCP preserves byte order rather than application message boundaries. Length prefixes or delimiters are common framing approaches.', 'Interprocess Communication'),
    ('A nonblocking receive finds no available data on an otherwise open connection. What should the application generally do?',
     '{"A":"Assume a complete message containing zero bytes arrived","B":"Assume the entire operating system has failed","C":"Treat the result as proof that the peer has terminated","D":"Handle the would-block result and wait for readiness or retry appropriately"}', 'D',
     'A would-block result indicates that data is not currently available. It is distinct from a successful EOF indication.', 'Interprocess Communication'),
    ('Two processes share a memory region but map it at different virtual addresses. Why is storing a raw pointer from one process in the region problematic?',
     '{"A":"The pointer value may not refer to the same object in the other process address space","B":"Shared memory can contain only single-bit values","C":"Every pointer automatically becomes a socket","D":"Different mappings always prohibit shared access"}', 'A',
     'Raw virtual addresses depend on each process mapping. Relative offsets or another agreed representation can avoid this mismatch.', 'Interprocess Communication'),
    ('What is a benefit of length-prefixed message framing over a byte stream?',
     '{"A":"It prevents all network disconnects","B":"It tells the receiver how many payload bytes belong to a record","C":"It guarantees that a whole message arrives in one read","D":"It removes all limits on message sizes"}', 'B',
     'A length field defines the record size. Receivers still need partial-read handling and validation of lengths before allocating or reading.', 'Interprocess Communication'),
    ('A request is processed, but its reply is lost. The client retries. What helps prevent the operation from being performed twice?',
     '{"A":"Giving every retry an unrelated request identity","B":"Ignoring all server state","C":"Reusing a request ID and having the server deduplicate processed requests","D":"Assuming networks never lose replies"}', 'C',
     'A stable request ID lets a server recognize a retry and return a prior result instead of repeating a non-idempotent operation.', 'Interprocess Communication'),
    ('A receiver reads only part of a length-prefixed payload before the connection closes. What should it conclude?',
     '{"A":"The missing bytes are automatically valid zeros","B":"The full record was delivered successfully","C":"The sender necessarily completed every requested action","D":"The record is incomplete and must be handled as a communication failure"}', 'D',
     'A partial payload is not a complete framed record. Applications must detect truncation and apply their error or retry policy.', 'Interprocess Communication'),
    ('A producer changes a condition predicate while holding the same mutex used by a waiting consumer. Why does this shared locking discipline matter?',
     '{"A":"It coordinates predicate checks and changes so the wait protocol can avoid missed notifications","B":"It guarantees the producer never fails","C":"It turns all memory into thread-local storage","D":"It makes condition variables count every historical event"}', 'A',
     'The predicate and wait protocol must use consistent synchronization. A condition-variable notification alone does not replace protected shared state.', 'Synchronization'),
    ('A semaphore tracks occupied slots in an initially empty bounded buffer. What should its initial count be?',
     '{"A":"The buffer capacity plus one","B":"Zero","C":"The number of CPU cores","D":"The maximum process ID"}', 'B',
     'There are initially no items to consume, so the occupied-slot count starts at zero and increases when producers publish items.', 'Synchronization'),
    ('Why is disabling interrupts on only one CPU generally insufficient to protect shared data from other CPUs?',
     '{"A":"It automatically stops every CPU in the system","B":"It makes the shared data immutable","C":"Other CPUs can continue executing and access the same data","D":"It forces every thread to terminate"}', 'C',
     'Local interrupt control affects the current CPU. Multiprocessor mutual exclusion also requires coordination with execution on other CPUs.', 'Synchronization'),
    ('Several readers can safely inspect a structure concurrently, but updates must exclude readers and other writers. Which abstraction matches this requirement?',
     '{"A":"An unprotected shared counter","B":"A thread name","C":"A process exit status","D":"A reader-writer lock"}', 'D',
     'A reader-writer lock can allow multiple shared read holders while requiring exclusive write ownership. Fairness depends on its policy.', 'Synchronization'),
    ('What is an atomic compare-and-swap operation intended to do?',
     '{"A":"Compare a location to an expected value and conditionally update it as one indivisible operation","B":"Copy every process address space to disk","C":"Wait until all threads reach a barrier","D":"Replace a comparison with an arbitrary sleep"}', 'A',
     'Compare-and-swap conditionally updates a location atomically. It is a building block for synchronization and concurrent algorithms.', 'Synchronization'),
    ('Why is repeatedly sleeping for a fixed interval a poor substitute for locking shared mutable data?',
     '{"A":"Sleeping makes every memory access atomic","B":"Timing delays do not guarantee mutual exclusion or a correct ordering of accesses","C":"Sleeping guarantees that no other thread runs","D":"A fixed interval automatically protects all objects"}', 'B',
     'Execution timing varies. Delays alone do not establish the synchronization guarantees required to prevent conflicting accesses.', 'Synchronization'),
    ('A thread calls a nonrecursive mutex lock operation twice without unlocking it. What risk does this create?',
     '{"A":"The mutex necessarily creates another thread","B":"All other locks are automatically released","C":"The thread may block on a lock it already owns or encounter API-defined error behavior","D":"The second call is guaranteed to succeed on every platform"}', 'C',
     'A nonrecursive mutex does not generally permit repeated acquisition by its owner. Exact behavior depends on the mutex API and configuration.', 'Synchronization'),
    ('What does fairness in a lock acquisition policy aim to reduce?',
     '{"A":"The amount of executable code on disk","B":"The number of virtual addresses","C":"The existence of shared state","D":"Indefinite postponement of particular waiting threads"}', 'D',
     'Fair acquisition policies limit repeated bypassing of waiters and can reduce starvation. They do not automatically prevent all deadlocks.', 'Synchronization'),
    ('A thread holding lock A tries to acquire lock B using try-lock. On failure it releases A before retrying. Which deadlock condition does this protocol try to avoid?',
     '{"A":"Holding one resource while blocking for another","B":"The existence of process IDs","C":"All use of shared memory","D":"The existence of time quanta"}', 'A',
     'Releasing A instead of waiting while holding it avoids hold and wait at that step. Poorly coordinated retries can still cause starvation or livelock.', 'Deadlock'),
    ('Why is a timeout alone not proof that a deadlock has occurred?',
     '{"A":"Deadlocks always resolve before any timeout","B":"A slow but progressing operation can also exceed the timeout","C":"Timeouts only exist in single-threaded programs","D":"A timeout automatically proves a circular wait"}', 'B',
     'Timeouts detect excessive delay, which can arise from slow work or contention as well as deadlock. Diagnosing a dependency cycle needs more evidence.', 'Deadlock'),
    ('With multiple instances of a resource type, a resource-allocation graph contains a cycle. What follows from the cycle alone?',
     '{"A":"Every process must be terminated immediately","B":"No process can ever finish","C":"Deadlock is possible but is not established solely by the cycle","D":"Every resource has exactly one instance"}', 'C',
     'Additional instances can permit a process to finish and break the wait. The single-instance cycle rule does not directly generalize.', 'Deadlock'),
    ('Two processes each need at most two identical resources to complete. Three instances exist, and each process currently holds one. Why is this state safe?',
     '{"A":"Both processes must release every resource immediately","B":"The system has no allocated resources","C":"Neither process will ever request another resource","D":"The remaining instance can let one process finish and release enough for the other"}', 'D',
     'One free instance can satisfy either process remaining need. Its completion releases two instances, allowing the other process to finish.', 'Deadlock'),
    ('Two processes each hold one of two identical resource instances and each waits for one more, retaining what it holds. With no preemption or outside release, what is the result?',
     '{"A":"Deadlock: neither can obtain the additional instance needed to proceed","B":"Both immediately complete","C":"A third resource is automatically created","D":"Waiting cannot occur for identical resources"}', 'A',
     'No free instance exists, and neither process can finish and release its held instance. Each depends on resources the other retains.', 'Deadlock'),
    ('What distinguishes deadlock detection from deadlock avoidance?',
     '{"A":"Detection requires that resource waits never occur","B":"Detection looks for an existing deadlock, while avoidance evaluates allocations to stay in safe states","C":"Avoidance waits until every process is deadlocked before acting","D":"Both terms only describe CPU burst prediction"}', 'B',
     'Detection identifies a deadlocked state after it arises. Avoidance uses resource-need information to reject allocations that would lead to unsafe states.', 'Deadlock'),
    ('A system chooses to recover from a deadlock by terminating one participating process. Why might this help?',
     '{"A":"Termination guarantees that all lost work is restored","B":"Termination adds physical CPU cores","C":"Reclaiming its resources can break the dependency cycle","D":"Every remaining process automatically becomes higher priority"}', 'C',
     'Reclaiming a victim resources may let others proceed. Recovery must account for lost work and consistency of partially completed operations.', 'Deadlock'),
    ('Why can resource preemption be difficult for deadlock recovery when the resource is a printer halfway through a document?',
     '{"A":"Printers cannot be shared by processes at different times","B":"Printing never has externally visible effects","C":"A printed page is automatically erased on preemption","D":"The partially completed physical output cannot necessarily be rolled back safely"}', 'D',
     'Some resources have effects that cannot be cleanly suspended and restored. Preemption is easier for resources with recoverable state.', 'Deadlock'),
    ('A page size is 4096 bytes. How many bits of a byte-addressed virtual address specify the offset within a page?',
     '{"A":"12 bits","B":"4 bits","C":"16 bits","D":"32 bits"}', 'A',
     '4096 equals 2 to the power 12, so the offset requires 12 bits.', 'Memory Management'),
    ('Virtual page 3 maps to physical frame 9, and the page size is 1024 bytes. What physical byte address corresponds to offset 100 in that page?',
     '{"A":"3172","B":"9316","C":"9100","D":"10240"}', 'B',
     'The physical address is frame number times page size plus offset: 9 * 1024 + 100 = 9316.', 'Memory Management'),
    ('A TLB lookup misses, but the referenced page is present in RAM with a valid page-table entry. What follows?',
     '{"A":"A disk read is always required","B":"The process must terminate","C":"The mapping can be obtained from the page table without loading the page from disk","D":"The virtual address becomes a process ID"}', 'C',
     'A TLB miss is not necessarily a page fault. If the page is resident, consulting the page table can supply the missing cached translation.', 'Memory Management'),
    ('What does copy-on-write allow after two processes initially share a memory page?',
     '{"A":"Both must immediately copy every page even if neither writes","B":"Both lose all read access permanently","C":"All writes are silently discarded","D":"A private copy can be created only when a process attempts to modify the shared page"}', 'D',
     'Copy-on-write defers copying until a write requires a private version, avoiding unnecessary copies for pages that remain unmodified.', 'Memory Management'),
    ('What does a page protection setting that denies writes help the OS enforce?',
     '{"A":"Detection of attempted writes to a read-only mapping","B":"Automatic completion of all I/O requests","C":"A unique CPU quantum for every byte","D":"The elimination of every page-table entry"}', 'A',
     'Hardware checks access permissions during memory references and can trap a disallowed write so the OS can handle it.', 'Memory Management'),
    ('Which page would least-recently-used replacement choose among resident pages last accessed at times 4, 9, and 12?',
     '{"A":"The page last accessed at time 12","B":"The page last accessed at time 4","C":"The page last accessed at time 9","D":"It must evict all three pages"}', 'B',
     'LRU selects the page with the oldest most recent access, which is time 4 in this example.', 'Memory Management'),
    ('Why can multi-level page tables save memory for a sparse virtual address space?',
     '{"A":"They remove every need for address translation","B":"They require every virtual page to be resident","C":"Lower-level tables need only be allocated for populated portions of the address space","D":"They replace all physical memory with CPU registers"}', 'C',
     'A hierarchy can omit lower-level tables covering unused address ranges instead of allocating one large entry array for the entire space.', 'Memory Management'),
    ('A process repeatedly accesses a small cluster of nearby memory locations. Which property does this illustrate?',
     '{"A":"Priority inversion","B":"Circular resource wait","C":"Process termination","D":"Spatial locality"}', 'D',
     'Spatial locality means nearby locations tend to be accessed close together in time. Temporal locality instead concerns reuse of the same locations.', 'Memory Management')
) AS seed(prompt, options, answer, explanation, concept_name)
JOIN concepts c ON c.name = seed.concept_name;
